import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import ghidra.program.model.symbol.*;import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.io.*;
public class settlement_CallGraph extends GhidraScript{
public void run()throws Exception{Function start=getFunctionAt(toAddr(0x5601c0));Map<Function,Function>parent=new HashMap<>();ArrayDeque<Function>q=new ArrayDeque<>();parent.put(start,null);q.add(start);try(PrintWriter out=new PrintWriter(Files.newBufferedWriter(Path.of(getScriptArgs()[0]),StandardCharsets.UTF_8))){out.println("root\t005601c0");while(!q.isEmpty()){Function f=q.remove();for(Function c:f.getCalledFunctions(monitor)){if(!parent.containsKey(c)){parent.put(c,f);q.add(c);}}}out.println("reachable_functions\t"+parent.size());for(long va:new long[]{0x561b00,0x561480}){Function t=getFunctionAt(toAddr(va));out.println("target\t"+t.getEntryPoint()+"\treachable\t"+parent.containsKey(t));if(parent.containsKey(t)){List<String>path=new ArrayList<>();for(Function a=t;a!=null;a=parent.get(a))path.add(a.getEntryPoint().toString());Collections.reverse(path);out.println(String.join(" -> ",path));}}List<Function>fs=new ArrayList<>(parent.keySet());fs.sort(Comparator.comparing(f->f.getEntryPoint()));for(Function f:fs){out.println("node\t"+f.getEntryPoint()+"\t"+f.getName()+"\tparent\t"+(parent.get(f)==null?"":parent.get(f).getEntryPoint()));}}}
}
